export function getSkillIcon(skillName: string): React.ComponentType<{ className?: string }> | null {
  const normalized = skillName.toLowerCase().trim();
  if (normalized === "react") return ReactIcon;
  if (normalized.includes("next")) return NextjsIcon;
  if (normalized.includes("vue")) return VueIcon;
  if (normalized === "typescript") return TypeScriptIcon;
  if (normalized === "javascript") return JavaScriptIcon;
  if (normalized.includes("tailwind")) return TailwindIcon;
  if (normalized.includes("flutter")) return FlutterIcon;
  if (normalized.includes("node")) return NodejsIcon;
  if (normalized.includes("express")) return ExpressIcon;
  if (normalized === "java") return JavaIcon;
  if (normalized.includes("python")) return PythonIcon;
  if (normalized.includes("php")) return PHPIcon;
  if (normalized.includes("laravel")) return LaravelIcon;
  if (normalized.includes("nest")) return NestjsIcon;
  if (normalized.includes("dart")) return DartIcon;
  if (normalized.includes("jwt")) return JWTIcon;
  if (normalized.includes("mysql")) return MySQLIcon;
  if (normalized.includes("postgres")) return PostgreSQLIcon;
  if (normalized.includes("mssql") || normalized.includes("ssms") || normalized.includes("sql server")) return MicrosoftSQLServerIcon;
  if (normalized.includes("firebase")) return FirebaseIcon;
  if (normalized.includes("supabase")) return SupabaseIcon;
  if (normalized.includes("mongo")) return MongoDBIcon;
  if (normalized.includes("git")) return GitIcon;
  if (normalized.includes("vs code") || normalized.includes("vscode")) return VSCodeIcon;
  if (normalized.includes("postman")) return PostmanIcon;
  if (normalized.includes("scalar")) return ScalarIcon;
  if (normalized.includes("swagger")) return SwaggerIcon;
  if (normalized.includes("prisma")) return PrismaIcon;
  if (normalized.includes("figma")) return FigmaIcon;
  return null;
}
